<?php
if (!defined('ABSPATH')) { exit; }

function rop_correct_add_game() {
    if (!is_user_logged_in()) { auth_redirect(); }
    $group_id = absint($_POST['group_id'] ?? 0);
    check_admin_referer('rop_add_game');
    $member = $group_id ? rop_member($group_id) : null;
    if (!$member) { wp_die('You do not have access to this group.', 403); }
    global $wpdb;
    $tables = rop_tables();
    $ids = array_map('absint', [$_POST['a1'] ?? 0, $_POST['a2'] ?? 0, $_POST['b1'] ?? 0, $_POST['b2'] ?? 0]);
    if (count(array_unique($ids)) !== 4 || in_array(0, $ids, true)) { rop_redirect(['group' => $group_id, 'rop_notice' => 'Choose four different players.']); }
    $valid_count = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tables['players']} WHERE group_id=" . $group_id . " AND id IN (" . implode(',', $ids) . ")");
    if ($valid_count !== 4) { wp_die('Invalid player selection.', 400); }
    $score_a = absint($_POST['score_a'] ?? 0); $score_b = absint($_POST['score_b'] ?? 0);
    if ($error = rop_validate_score_v13($score_a, $score_b)) { rop_redirect(['group' => $group_id, 'rop_notice' => $error]); }
    $wpdb->insert($tables['games'], [
        'group_id' => $group_id,
        'played_at' => rop_game_date_from_request($_POST['played_at'] ?? ''),
        'team_a1' => $ids[0], 'team_a2' => $ids[1],
        'team_b1' => $ids[2], 'team_b2' => $ids[3],
        'score_a' => $score_a, 'score_b' => $score_b,
    ], ['%d','%s','%d','%d','%d','%d','%d','%d']);
    // Land on the freshly recalculated standings instead of returning to scores.
    wp_safe_redirect(add_query_arg([
        'group' => $group_id,
        'rop_notice' => 'Game saved.',
        'rop_stats' => 1,
    ], home_url('/')) . '#rallyop-performance');
    exit;
}
add_action('admin_post_rop_correct_add_game', 'rop_correct_add_game', -999);

function rop_correct_edit_game() {
    if (!is_user_logged_in()) { auth_redirect(); }
    check_admin_referer('rop_edit_game');
    global $wpdb;
    $tables = rop_tables();
    $game_id = absint($_POST['game_id'] ?? 0);
    $game = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$tables['games']} WHERE id=%d", $game_id));
    $member = $game ? rop_member((int) $game->group_id) : null;
    if (!$game || !$member || $member->role !== 'owner') { wp_die('Only the group owner can edit games.', 403); }
    $ids = array_map('absint', [$_POST['a1'] ?? 0, $_POST['a2'] ?? 0, $_POST['b1'] ?? 0, $_POST['b2'] ?? 0]);
    if (count(array_unique($ids)) !== 4 || in_array(0, $ids, true)) { rop_redirect(['group' => $game->group_id, 'rop_notice' => 'Choose four different players.']); }
    $valid_count = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tables['players']} WHERE group_id=" . (int) $game->group_id . " AND id IN (" . implode(',', $ids) . ")");
    if ($valid_count !== 4) { wp_die('Invalid player selection.', 400); }
    $score_a = absint($_POST['score_a'] ?? 0); $score_b = absint($_POST['score_b'] ?? 0);
    if ($error = rop_validate_score_v13($score_a, $score_b)) { rop_redirect(['group' => $game->group_id, 'rop_notice' => $error]); }
    $played_at = rop_game_date_from_request($_POST['played_at'] ?? '');
    $updated = $wpdb->query($wpdb->prepare(
        "UPDATE {$tables['games']} SET played_at=%s, team_a1=%d, team_a2=%d, team_b1=%d, team_b2=%d, score_a=%d, score_b=%d WHERE id=%d",
        $played_at, $ids[0], $ids[1], $ids[2], $ids[3], $score_a, $score_b, $game_id
    ));
    if ($updated === false) { wp_die('The game could not be updated. Please try again.', 500); }
    wp_safe_redirect(add_query_arg(['group' => $game->group_id, 'rop_notice' => 'Game updated.'], home_url('/')) . '#clubhouse');
    exit;
}
add_action('admin_post_rop_correct_edit_game', 'rop_correct_edit_game', -999);

add_action('template_redirect', function() {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST' || empty($_POST['rop_front_edit']) || !is_user_logged_in()) { return; }
    check_admin_referer('rop_edit_game');
    global $wpdb;
    $tables = rop_tables();
    $game_id = absint($_POST['game_id'] ?? 0);
    $game = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$tables['games']} WHERE id=%d", $game_id));
    $member = $game ? rop_member((int) $game->group_id) : null;
    if (!$game || !$member || $member->role !== 'owner') { wp_die('Only the group owner can edit games.', 403); }
    $ids = array_map('absint', [$_POST['a1'] ?? 0, $_POST['a2'] ?? 0, $_POST['b1'] ?? 0, $_POST['b2'] ?? 0]);
    $posted_names = array_map('sanitize_text_field', [$_POST['a1_name'] ?? '', $_POST['a2_name'] ?? '', $_POST['b1_name'] ?? '', $_POST['b2_name'] ?? '']);
    if (!in_array('', $posted_names, true)) {
        $ids = array_map(function($name) use ($wpdb, $tables, $game) {
            return (int) $wpdb->get_var($wpdb->prepare("SELECT id FROM {$tables['players']} WHERE group_id=%d AND name=%s LIMIT 1", $game->group_id, $name));
        }, $posted_names);
    }
    if (count(array_unique($ids)) !== 4 || in_array(0, $ids, true)) { rop_redirect(['group' => $game->group_id, 'rop_notice' => 'Choose four different players.']); }
    $valid_count = (int) $wpdb->get_var("SELECT COUNT(*) FROM {$tables['players']} WHERE group_id=" . (int) $game->group_id . " AND id IN (" . implode(',', $ids) . ")");
    if ($valid_count !== 4) { wp_die('Invalid player selection.', 400); }
    $score_a = absint($_POST['score_a'] ?? 0); $score_b = absint($_POST['score_b'] ?? 0);
    if ($error = rop_validate_score_v13($score_a, $score_b)) { rop_redirect(['group' => $game->group_id, 'rop_notice' => $error]); }
    $played_at = rop_game_date_from_request($_POST['played_at'] ?? '');
    $wpdb->query($wpdb->prepare(
        "UPDATE {$tables['games']} SET played_at=%s, team_a1=%d, team_a2=%d, team_b1=%d, team_b2=%d, score_a=%d, score_b=%d WHERE id=%d",
        $played_at, $ids[0], $ids[1], $ids[2], $ids[3], $score_a, $score_b, $game_id
    ));
    wp_safe_redirect(add_query_arg(['group' => $game->group_id, 'rop_notice' => 'Game updated.'], home_url('/')) . '#clubhouse');
    exit;
}, -999);

add_action('template_redirect', function() {
    if ($_SERVER['REQUEST_METHOD'] !== 'POST' || empty($_POST['rop_front_delete']) || !is_user_logged_in()) { return; }
    check_admin_referer('rop_edit_game');
    global $wpdb;
    $tables = rop_tables();
    $game_id = absint($_POST['game_id'] ?? 0);
    $game = $wpdb->get_row($wpdb->prepare("SELECT * FROM {$tables['games']} WHERE id=%d", $game_id));
    $member = $game ? rop_member((int) $game->group_id) : null;
    if (!$game || !$member || $member->role !== 'owner') { wp_die('Only the group owner can delete games.', 403); }
    $wpdb->delete($wpdb->prefix . 'rallyop_game_reactions', ['game_id' => $game_id, 'group_id' => (int) $game->group_id], ['%d', '%d']);
    $wpdb->delete($wpdb->prefix . 'rallyop_game_comments', ['game_id' => $game_id, 'group_id' => (int) $game->group_id], ['%d', '%d']);
    $wpdb->delete($tables['games'], ['id' => $game_id], ['%d']);
    rop_redirect(['group' => $game->group_id, 'rop_notice' => 'Game deleted.']);
}, -999);

add_action('template_redirect', function() {
    if (!is_front_page() || !is_user_logged_in() || isset($_GET['join'])) { return; }
    $user_id = get_current_user_id();
    $requested = absint($_GET['group'] ?? 0);
    if ($requested && rallyop_can_access_group($requested)) {
        update_user_meta($user_id, 'rallyop_last_group_id', $requested);
        return;
    }
    if ($requested) { return; }
    $last_group = absint(get_user_meta($user_id, 'rallyop_last_group_id', true));
    if (!$last_group || !rallyop_can_access_group($last_group)) { return; }
    $args = ['group' => $last_group];
    if (!empty($_GET['rop_notice'])) { $args['rop_notice'] = sanitize_text_field(wp_unslash($_GET['rop_notice'])); }
    wp_safe_redirect(add_query_arg($args, home_url('/')) . '#clubhouse');
    exit;
}, 8);

